<?php
namespace App\Filament\Resources\VoiceReportResource\RelationManagers;
use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\RelationManagers\RelationManager; use Filament\Tables; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class AudioClipsRelationManager extends RelationManager { protected static string $relationship='audioClips'; protected static ?string $title='Extraits audio';
 public function form(Form $form): Form{return $form->schema([Forms\Components\Section::make('Lecture')->schema([Forms\Components\Placeholder::make('player')->label('Lecteur')->content(fn($record)=>view('filament.tables.audio-player',['getRecord'=>fn()=> $record]))])->columnSpanFull(),Forms\Components\Section::make('Détails')->columns(2)->schema([Forms\Components\TextInput::make('reported_user_discord_id')->label('Utilisateur')->formatStateUsing(fn($state,$record)=>$record?->displayName()??$state)->disabled(),Forms\Components\TextInput::make('status')->label('Statut')->disabled(),Forms\Components\TextInput::make('mime_type')->label('Format')->disabled(),Forms\Components\TextInput::make('size_bytes')->label('Taille')->formatStateUsing(fn($state):string=>number_format(((int)$state)/1024/1024,2,',',' ').' Mo')->disabled(),Forms\Components\TextInput::make('duration_seconds')->label('Durée')->suffix(' s')->disabled(),Forms\Components\DateTimePicker::make('captured_from')->label('Début')->disabled(),Forms\Components\DateTimePicker::make('captured_until')->label('Fin')->disabled(),Forms\Components\TextInput::make('storage_path')->label('Chemin')->disabled()->columnSpanFull(),Forms\Components\Textarea::make('error_message')->label('Erreur')->disabled()->columnSpanFull()])]);}
 public function table(Table $table): Table{return $table->modifyQueryUsing(fn(Builder $query)=>$query->latest('captured_until'))->poll('10s')->columns([Tables\Columns\ViewColumn::make('player')->label('Extrait')->view('filament.tables.audio-player')])->filters([Tables\Filters\SelectFilter::make('reported_user_discord_id')->label('Utilisateur')->options(fn():array=>$this->getOwnerRecord()->audioClips()->get()->mapWithKeys(fn($clip)=>[$clip->reported_user_discord_id=>$clip->displayName()])->all()),Tables\Filters\SelectFilter::make('status')->label('Statut')->options(['captured'=>'Capturé','processing'=>'Traitement','ready'=>'Prêt','failed'=>'Échec','deleted'=>'Supprimé'])])->actions([Tables\Actions\Action::make('listen')->label('Ouvrir')->icon('heroicon-o-speaker-wave')->url(fn($record):string=>route('admin.audio-clips.stream',$record))->openUrlInNewTab(),Tables\Actions\Action::make('download')->label('Télécharger')->icon('heroicon-o-arrow-down-tray')->url(fn($record):string=>route('admin.audio-clips.stream',$record))->openUrlInNewTab(),Tables\Actions\EditAction::make()->label('Détails'),Tables\Actions\DeleteAction::make()->label('Supprimer')])->bulkActions([Tables\Actions\DeleteBulkAction::make()->label('Supprimer la sélection')])->emptyStateHeading('Aucun extrait audio')->emptyStateDescription('Les extraits apparaissent ici après un signalement effectué juste après une prise de parole dans un salon surveillé.');}
}
